<?php

declare(strict_types=1);

namespace ZionConnector;

final class AdminConsole
{
    public static function render(): string
    {
        return <<<'HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Zion Connector · Debug Console</title>
<style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#080d16;color:#e8eef7}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#14263b 0,#080d16 42%);min-height:100vh}button,input,select{font:inherit}.shell{width:min(1660px,calc(100% - 40px));margin:0 auto;padding:32px 0 48px}.topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:24px}.eyebrow{color:#f29a49;font:11px/1.3 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.16em;text-transform:uppercase}.topbar h1{margin:8px 0 7px;font-size:30px;letter-spacing:-.04em}.topbar p{margin:0;color:#8ea0b5;font-size:13px}.debug-pill{display:inline-flex;align-items:center;gap:7px;padding:8px 11px;border:1px solid #235a4b;border-radius:999px;background:#102a25;color:#7de0bd;font-size:11px}.debug-pill i{width:7px;height:7px;border-radius:50%;background:#36d49b;box-shadow:0 0 12px #36d49b}.filters{display:grid;grid-template-columns:minmax(220px,1fr) 150px 150px 130px 130px auto auto;gap:9px;padding:14px;border:1px solid #203248;border-radius:14px;background:#0c1522;box-shadow:0 14px 50px #0003}.filters input,.filters select{min-width:0;padding:10px 11px;color:#dbe7f5;border:1px solid #243a52;border-radius:8px;background:#101d2d;outline:none}.filters input:focus,.filters select:focus{border-color:#f29a49;box-shadow:0 0 0 3px #f29a4926}.button{padding:10px 13px;color:#e8eef7;border:1px solid #2c425b;border-radius:8px;background:#142338;cursor:pointer}.button:hover{border-color:#f29a49}.button.danger{color:#ffabb0;border-color:#67323c;background:#29151b}.summary{display:flex;align-items:center;justify-content:space-between;margin:14px 2px;color:#8093a9;font-size:11px}.table-wrap{overflow:auto;border:1px solid #203248;border-radius:14px;background:#0c1522}.row{display:grid;grid-template-columns:140px 105px 76px minmax(240px,1.35fr) minmax(180px,.8fr) minmax(180px,.8fr) 65px 65px;align-items:start;gap:12px;min-width:1200px;min-height:58px;padding:10px 15px;border-bottom:1px solid #1a2b3e;color:#9fb0c3;font-size:11px;cursor:pointer}.row>*{min-width:0;text-align:left}.row:last-child{border-bottom:0}.row:hover{background:#111f30}.row.head{min-height:38px;align-items:center;color:#657a91;background:#0a111c;font:10px ui-monospace,SFMono-Regular,Menlo,monospace;text-transform:uppercase;letter-spacing:.08em;cursor:default}.row strong{display:block;overflow:hidden;color:#e8eef7;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.row code{display:block;overflow:hidden;color:#8fc5ff;text-overflow:ellipsis;white-space:nowrap}.method{display:inline-flex;width:max-content;padding:4px 6px;border:1px solid #2a4969;border-radius:5px;color:#9fcfff;background:#102238;font:10px ui-monospace,SFMono-Regular,Menlo,monospace}.source{color:#f4b36f;line-height:1.45}.context{display:block;overflow:hidden;line-height:1.35}.context strong{display:block;overflow:hidden;color:#d9e8f7;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.context small{display:block;margin-top:3px;color:#71869e;font-size:9px;text-transform:uppercase;letter-spacing:.08em}.context.muted strong{color:#71869e;font-weight:500}.status{display:inline-flex;width:max-content;padding:4px 6px;border-radius:5px;font:10px ui-monospace,SFMono-Regular,Menlo,monospace}.status.ok{color:#75e2bb;background:#102c25}.status.fail{color:#ff9ca4;background:#301820}.status.neutral{color:#a8bbcf;background:#172435}.detail{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:1px -15px -10px;padding:16px;background:#080f19;cursor:default}.detail h3{margin:0 0 7px;color:#f29a49;font:10px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.1em;text-transform:uppercase}.association{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:10px 12px;border:1px solid #1d344b;border-radius:8px;background:#0c1827;text-align:left}.association b{display:block;color:#71869e;font-size:9px;text-transform:uppercase;letter-spacing:.08em}.association span{display:block;margin-top:3px;color:#dbe7f5;font-size:12px;overflow-wrap:anywhere}.detail pre{display:block;width:100%;max-height:310px;overflow:auto;margin:0;padding:13px;color:#d6e5f5;border:1px solid #203248;border-radius:9px;background:#060a10;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;text-align:left;direction:ltr;white-space:pre-wrap;overflow-wrap:anywhere}.json{text-align:left!important}.json .key{color:#8bc7ff}.json .string{color:#a8e6a2}.json .number{color:#f4c47a}.json .boolean{color:#e5a8ff}.json .null{color:#91a4bb}.empty,.loading{padding:48px;text-align:center;color:#788ca2}.error{margin:14px 0;padding:12px;color:#ffabb0;border:1px solid #67323c;border-radius:9px;background:#29151b}.pagination{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:16px;color:#8ea0b5;font-size:11px}.pagination button:disabled{cursor:not-allowed;opacity:.4}@media(max-width:1100px){.filters{grid-template-columns:1fr 1fr 1fr}.filters input{grid-column:1/-1}.row{grid-template-columns:120px 80px 70px minmax(180px,1fr) minmax(150px,.8fr) minmax(150px,.8fr) 65px 65px}}@media(max-width:700px){.shell{width:min(100% - 22px,1660px);padding-top:20px}.topbar{display:block}.debug-pill{margin-top:15px}.filters{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr 1fr;min-width:0;gap:7px;padding:12px}.row.head{display:none}.row>*{grid-column:auto}.row > :nth-child(4),.row > :nth-child(5),.row > :nth-child(6),.detail{grid-column:1/-1}.detail{grid-template-columns:1fr;margin:3px -12px -12px;padding:12px}.association{grid-template-columns:1fr}.summary{display:block;line-height:1.8}}
</style>
</head>
<body>
<main class="shell">
<header class="topbar"><div><div class="eyebrow">ZION CONNECTOR / ADMIN</div><h1>Debug Console</h1><p>Inspect redacted communication between Release Station, Zion Connector and GitHub.</p></div><span class="debug-pill"><i></i>APP_DEBUG is enabled</span></header>
<section class="filters"><input id="q" type="search" placeholder="Search request id, URL, repository or site…"><select id="direction"><option value="">All directions</option><option value="inbound">Inbound</option><option value="outbound">Outbound</option></select><select id="source"><option value="">All sources</option><option value="synology">Synology</option><option value="github">GitHub</option></select><select id="method"><option value="">All methods</option><option>GET</option><option>POST</option><option>PUT</option><option>DELETE</option><option>PATCH</option></select><select id="status"><option value="">All status</option><option value="2">2xx</option><option value="4">4xx</option><option value="5">5xx</option></select><button class="button" id="refresh">Refresh</button><button class="button danger" id="clear">Clear logs</button></section>
<div class="summary"><span id="summary">Loading logs…</span><span>Auto-refresh: 3 seconds · secrets redacted</span></div>
<section class="table-wrap"><div class="row head"><span>Time</span><span>Direction</span><span>Method</span><span>URL / request id</span><span>GitHub repository</span><span>Release Station site</span><span>Status</span><span>Duration</span></div><div id="rows" class="loading">Loading logs…</div></section>
<nav class="pagination"><button class="button" id="previous">Previous</button><span id="page">Page 1</span><button class="button" id="next">Next</button></nav>
</main>
<script>
const state={page:1,perPage:50,items:[],expanded:null};
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function pretty(value){if(!value)return '';try{return JSON.stringify(JSON.parse(value),null,2)}catch{return String(value)}}
function highlight(value){let text=esc(pretty(value));return text.replace(/(&quot;(?:\\.|[^&])*?&quot;)(\s*:)?/g,(m,s,k)=>k?'<span class="key">'+s+'</span>'+k:'<span class="string">'+s+'</span>').replace(/\b(true|false)\b/g,'<span class="boolean">$1</span>').replace(/\b(null)\b/g,'<span class="null">$1</span>').replace(/(^|[^\w])(-?\d+(?:\.\d+)?)(?=[^\w]|$)/g,'$1<span class="number">$2</span>')}
function statusClass(status){return status>=500?'fail':status>=400?'neutral':'ok'}
function filters(){const status=$("status").value;return new URLSearchParams({q:$("q").value,direction:$("direction").value,source:$("source").value,method:$("method").value,status:status?status:'',page:state.page,per_page:state.perPage}).toString()}
function valueOrFallback(value,fallback='Not associated'){const normalized=String(value??'').trim();return normalized?normalized:fallback}
function siteValue(item){return valueOrFallback(item.release_station_site||item.release_station_url||(item.release_station_site_id?'Site '+item.release_station_site_id:'')||(item.release_station_instance_id?'Instance '+item.release_station_instance_id:''))}
function contextCell(value,label){const muted=!value||value==='Not associated';return '<span class="context '+(muted?'muted':'')+'"><strong>'+esc(valueOrFallback(value))+'</strong><small>'+label+'</small></span>'}
async function load(){try{const response=await fetch('/admin/api/logs?'+filters(),{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Debug API returned '+response.status);const payload=await response.json();state.items=payload.data?.items||[];render(payload.data?.total||0)}catch(error){$('rows').innerHTML='<div class="error">'+esc(error.message)+'</div>'}}
function render(total){$('summary').textContent=total+' log entries · '+state.items.length+' shown';$('page').textContent='Page '+state.page;$("previous").disabled=state.page<=1;$("next").disabled=state.page*state.perPage>=total;if(!state.items.length){$('rows').innerHTML='<div class="empty">No matching debug entries.</div>';return}$('rows').innerHTML=state.items.map(item=>{const open=state.expanded===item.id;const repository=valueOrFallback(item.github_repository);const site=siteValue(item);return '<div class="row" data-id="'+item.id+'"><span>'+esc(new Date(item.created_at).toLocaleString())+'</span><span class="source">'+esc(item.direction)+' · '+esc(item.source)+'</span><span class="method">'+esc(item.method)+'</span><span><strong>'+esc(item.url)+'</strong><code>'+esc(item.request_id)+'</code></span>'+contextCell(repository,'GitHub repository')+contextCell(site,'Release Station site')+'<span class="status '+statusClass(Number(item.status))+'">'+esc(item.status)+'</span><span>'+esc(item.duration_ms)+'ms</span>'+(open?'<div class="detail"><div class="association"><div><b>GitHub repository</b><span>'+esc(repository)+'</span></div><div><b>Release Station site</b><span>'+esc(site)+(item.release_station_site_id?' · '+esc(item.release_station_site_id):'')+'</span></div></div><section><h3>Request headers</h3><pre class="json">'+highlight(item.request_headers_json)+'</pre><h3 style="margin-top:12px">Request body</h3><pre class="json">'+highlight(item.request_body)+'</pre></section><section><h3>Response headers</h3><pre class="json">'+highlight(item.response_headers_json)+'</pre><h3 style="margin-top:12px">Response body</h3><pre class="json">'+highlight(item.response_body)+'</pre></section></div>':'')+'</div>'}).join('');document.querySelectorAll('.row[data-id]').forEach(row=>row.addEventListener('click',event=>{if(event.target.closest('.detail'))return;state.expanded=state.expanded===Number(row.dataset.id)?null:Number(row.dataset.id);render(total)}))}
['q','direction','source','method','status'].forEach(id=>$(id).addEventListener('input',()=>{state.page=1;load()}));$('refresh').addEventListener('click',load);$('previous').addEventListener('click',()=>{if(state.page>1){state.page--;load()}});$('next').addEventListener('click',()=>{state.page++;load()});$('clear').addEventListener('click',async()=>{if(!confirm('Delete all debug logs?'))return;await fetch('/admin/api/logs',{method:'DELETE'});state.page=1;load()});load();setInterval(load,3000);
</script>
</body>
</html>
HTML;
    }
}
